//On se positionne dans le fichier sur la machine sélectionnée dans la table
HLitRecherchePremier(MACHINE,NomMachine,TABLE_Machines.COL_Machine)

//Si la machine n'est pas dans un lieu
si machine.IDLieu <> 0 alors

	//Sinon on affiche un cadre rouge autour du lieu où se situe la machine
	HLitRecherchePremier(LIEU,IDLieu,machine.IDLieu)
	EntoureLieu(lieu.Rectangle)

fin

nIDmachine est un entier = TABLE_Machines.COL_IDMachine

//On ouvre la fenêtre de visualisation - modification de la machine sélectionnée dans la table
bModif est un booleen = ouvre(FEN_Machine, nIDmachine)

//Si on a changé le nom de la machine pendant la modification, on met à jour la table
si bModif = vrai alors

	//Met à jour la table au cas où les informations de la machine aient été modifiées 
	//Si on avait un ID de lieu mémorisé : on affiche les machines de ce lieu sinon on affiche toutes les machines
	si gnIDLieu = 0 ALORS
		AfficheToutesMachines()
	sinon
		AfficheMachinesLieu(gnIDLieu)
	FIN

	//Remet le bandeau de la table sur la machine qui a été visualisée - modifiée
	nIndice est un entier = TableCherche(COL_idMachine, nIDmachine)
	TableSelectPlus(TABLE_Machines,nIndice)

	//Ré-affichage du plan : si on a modifié le lieu d'une machine ...
	AffichePlan(IMG_PlanLocaux)

	HLitRecherchePremier(lieu, IDLieu, machine.IDLieu)
	EntoureLieu(LIEU.Rectangle)

FIN

si TableSelect(TABLE_Machines) = -1 alors retour

//1 : Et tous ses composants ?
//2 : Et son UC et mettre les autres composants dans le stock ?
//3 : Ne rien faire
SELON Dialogue(<§?183C306901A0BAB1§>, TABLE_Machines.COL_Machine)

	// Et tous ses composants ?
	CAS 1 :

		POUR TOUT COMPOSANT AVEC NomMachine = TABLE_Machines.COL_Machine
			HSupprime(COMPOSANT)
		FIN

		//On supprime la machine correspondant à la sélection dans la table
		HLitRecherchepremier(MACHINE,NomMachine,TABLE_Machines.COL_Machine)
		HSupprime(MACHINE)

		//Met à jour la table
		//Si on avait un ID de lieu mémorisé : on affiche les machines de ce lieu sinon on affiche toutes les machines
		SI gnIDLieu = 0 ALORS
			AfficheToutesMachines()
		SINON
			AfficheMachinesLieu(gnIDLieu)
		FIN

	// Et son UC et mettre les autres composants dans le stock ?
	CAS 2 :

		POUR TOUT COMPOSANT AVEC NomMachine = TABLE_Machines.COL_Machine

			//On va chercher le type du composant
			//Si c'est l'unité centrale : on supprime
			//sinon on met le composant dans le stock

			HLitRecherchepremier(Modele,IDMODELE,COMPOSANT.IDMODELE)
			SI Modele.TypeModele = CST_TypeUC ALORS
				HSupprime(COMPOSANT)
			SINON
				COMPOSANT.NomMachine=""
				HModifie(COMPOSANT)	
			FIN

		FIN

		//On supprime la machine correspondant à la sélection dans la table
		HLitRecherchePremier(MACHINE,NomMachine,TABLE_Machines.COL_Machine)
		HSupprime(MACHINE)

		//Met à jour la table
		//Si on avait un ID de lieu mémorisé : on affiche les machines de ce lieu sinon on affiche toutes les machines
		SI gnIDLieu = 0 ALORS
			AfficheToutesMachines()
		SINON
			AfficheMachinesLieu(gnIDLieu)
		FIN	

	// Ne rien faire
	CAS 3 :

FIN

//Ouverture de la fenêtre de création d'une nouvelle machine
sNomMachine est une chaine = Ouvre(FEN_Machine)

//Si effectivement on a créé une nouvelle machine, on met à jour la table 
si sNomMachine <> "" alors

	//Met à jour la table avec la nouvelle machine
	//Si on avait un ID de lieu mémorisé : on affiche les machines de ce lieu sinon on affiche toutes les machines
	SI gnIDLieu = 0 ALORS
		AfficheToutesMachines()
	SINON
		AfficheMachinesLieu(gnIDLieu)
	FIN

	//Remet le bandeau de la table sur la machine qui a été créée et la sélectionne
	nIndice est un entier = TableCherche(COL_Machine, sNomMachine)
	TableSelectPlus(TABLE_Machines,nIndice)

fin

